#!/usr/bin/env python3 import os import json import time import requests PROJECT_ROOT = "/data/data/com.termux/files/home/KAI_9000" TODO_DIR = "/data/data/com.termux/files/home/.qwen/todos" SERVER_URL = "http://127.0.0.1:9000/api/brew" def get_active_todo_file(): if not os.path.exists(TODO_DIR): return None files = [f for f in os.listdir(TODO_DIR) if f.endswith('.json')] if not files: return None # take the first todo list for now return os.path.join(TODO_DIR, files[0]) def load_todos(filepath): try: with open(filepath, 'r') as f: return json.load(f) except Exception as e: print(f"Error loading todos: {e}") return None def save_todos(filepath, data): try: with open(filepath, 'w') as f: json.dump(data, f, indent=2) except Exception as e: print(f"Error saving todos: {e}") def run_autonomous_loop(): todo_file = get_active_todo_file() if not todo_file: print("No granular list found.") return data = load_todos(todo_file) if not data or 'todos' not in data: print("Invalid todo list format.") return todos = data['todos'] print(f"Found granular list: {todo_file}") for task in todos: if task.get('status') in ['completed', 'done']: continue task_id = task.get('id') content = task.get('content') print(f"\n[+] Executing Task {task_id}: {content}") # Mark as in progress task['status'] = 'in_progress' save_todos(todo_file, data) # Send to KAI_9000 Pedagogy Server payload = { "prompt": f"Write a bash or python script to accomplish this task: '{content}'. The script must execute automatically. Do not include interactive prompts." } try: print(" -> Brewing code via LLM API...") response = requests.post(SERVER_URL, json=payload, timeout=120) result = response.json() if result.get("success"): print(" -> Execution successful!") print(f" -> Response: {result.get('execution_summary', '')[:100]}...") task['status'] = 'completed' else: print(f" -> Execution failed: {result.get('error', 'Unknown error')}") task['status'] = 'failed' except requests.exceptions.RequestException as e: print(f" -> Server connection failed: {e}") task['status'] = 'pending' # Revert to pending break # Stop loop if server is down # Save state after each task save_todos(todo_file, data) # Add a sleep gap for thermal throttling / API limits time.sleep(5) print("\nAutonomous loop finished.") if __name__ == "__main__": # Ensure server is reachable before starting try: requests.get("http://127.0.0.1:9000/api/status", timeout=5) run_autonomous_loop() except requests.exceptions.RequestException: print("KAI_9000 Pedagogy Server is not running. Please start it first.")
